//! Файл: settings/catalog/book_events.rs
//! Что делает: настройка решения 324 — стаканы бирж не теряются при полном канале событий ядра (раздел «Площадки»,
//! область «вся система» и «площадка»). Отдельный файл: base.rs — общий для многих задач. Необязательная, значения нет.
//! Кто вызывает: settings/catalog/mod.rs.
//! От чего зависит: settings/catalog/mod.rs (короткая запись d и наборы областей).
//! Настройки: это и есть их список (зеркало docs/SETTINGS.md, раздел «Площадки»).

use super::{GV, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Настройки решения 324. Порядок — как в docs/SETTINGS.md.
#[rustfmt::skip]
pub static BOOK_EVENTS: &[SettingDef] = &[
    d("Площадки", "venue.book_events_keep", K::Bool, L::None, "да/нет", GV, "Решение 324 (биржи): кадр стакана (MarketEvent::Book), не вошедший в канал событий ядра (канал полон — ёмкость --live-buffer), НЕ теряется: последний кадр каждой пары (площадка, тикер) ждёт в общем наборе канала ядра (не больше числа пар, без дублей; стакан ядру — полный, последний заменяет прежние) и уходит ядру, как только в канале появится место — в общей очереди с событиями пулов DEX (решение 321), по порядку откладывания, без голодания. Время получения кадра не меняется — устаревший кадр ядро отбросит по своим правилам свежести. Запись журнала venue.book_events_lost (интервал log.pool_events_lost_interval_s) — «отложено, заменено, доставлено, потеряно, ждут». Включать вместе с dex.pool_events_keep: иначе ждущие события пулов забирают каждое освободившееся место раньше кадров стаканов. Нет или не задана — как раньше: кадр при полном канале потерян (ядро пересчитает пару только по следующему кадру). «Стакан недостоверен» (Invalidated) не теряется при любом значении").optional(),
];
